(function(){var root=document.documentElement;root.classList.remove("no-js");try{var saved=localStorage.getItem("theme");var prefersDark=window.matchMedia&&window.matchMedia("(prefers-color-scheme:dark)").matches;var mode=(saved==="dark"||saved==="light")?saved:"system";var effective=(saved==="dark"||saved==="light")?saved:(prefersDark?"dark":"light");root.setAttribute("data-theme",effective);root.setAttribute("data-theme-mode",mode);}catch(e){var prefersDarkFallback=window.matchMedia&&window.matchMedia("(prefers-color-scheme:dark)").matches;root.setAttribute("data-theme",prefersDarkFallback?"dark":"light");root.setAttribute("data-theme-mode","system");}})();